"""K-105: a GitHub App cannot be limited to folders, so CI checks that a PR
opened by a role's App only touches that role's paths. Rules come from
.github/role-paths.json (generated by domatapp-agents/scripts/export-role-paths.mjs).
Patterns are globs; a leading "!" excludes. PRs by people are not checked.
Runs from the base branch (pull_request_target), so the rules are the base's."""
import fnmatch
import json
import subprocess
import sys


def allowed(path, patterns):
    ok = False
    for p in patterns:
        neg = p.startswith("!")
        glob = (p[1:] if neg else p).replace("**", "*")
        if fnmatch.fnmatchcase(path, glob):
            ok = not neg
    return ok


def main():
    author, base, head = sys.argv[1:4]
    with open(".github/role-paths.json", encoding="utf-8") as fh:
        rules = json.load(fh)
    if author not in rules:
        print(f"{author}: not an agent App, nothing to check")
        return 0
    # -z + --no-renames + core.quotePath=false so paths with spaces, non-ASCII, or
    # renames (which become delete-old + add-new, both checked) can't slip the gate.
    out = subprocess.run(
        ["git", "-c", "core.quotePath=false", "diff", "--no-renames", "--name-only", "-z",
         f"{base}...{head}"],
        check=True, capture_output=True,
    ).stdout
    files = [p.decode("utf-8", "surrogateescape") for p in out.split(b"\0") if p]
    bad = [f for f in files if not allowed(f, rules[author])]
    for f in bad:
        print(f"::error file={f}::{author} may not change {f} (K-105)")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())
